#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <WiFi.h>
#include <WebServer.h>

// Пины XIAO ESP32-C3: D0=GPIO2 A0, D1=GPIO3, D2=GPIO4, D3=GPIO5, SDA=D4=GPIO6, SCL=D5=GPIO7, D10=GPIO10
#define PIN_SOIL A0  // D0 / GPIO2
#define PIN_BTN 3    // D1
#define PIN_LED_OK 4 // D2
#define PIN_LED_DRY 5 // D3
#define PIN_BUZZ 10  // D10 via transistor Q1

#define SDA_PIN 6
#define SCL_PIN 7
#define OLED_W 128
#define OLED_H 64
Adafruit_SSD1306 display(OLED_W, OLED_H, &Wire, -1);

const char* WIFI_SSID="YOUR_SSID";
const char* WIFI_PASS="YOUR_PASS";
WebServer server(80);

int dryValue=2600; // значение в воздухе (сухо)
int wetValue=1100; // в воде (мокро)
int threshold=30; // % ниже - тревога
int moisturePct=0;
int rawVal=0;
unsigned long lastBuzz=0;
bool alarm=false;

int readSoil(){
  long sum=0;
  for(int i=0;i<16;i++){ sum+=analogRead(PIN_SOIL); delay(5); }
  return sum/16;
}
int toPercent(int raw){
  int p = map(raw, dryValue, wetValue, 0, 100);
  return constrain(p,0,100);
}
void handleRoot(){
  String html="<meta charset=utf-8><h1>Датчик влажности</h1><p>Сырость: "+String(moisturePct)+"% (raw "+String(rawVal)+")</p>";
  html+="<p>Сухо в возд. "+String(dryValue)+" мокро "+String(wetValue)+" порог "+String(threshold)+"%</p>";
  html+="<p><a href='/api'>/api JSON</a></p>";
  server.send(200,"text/html",html);
}
void handleApi(){
  String j="{\"moisture\":"+String(moisturePct)+",\"raw\":"+String(rawVal)+",\"alarm\":"+String(alarm?"true":"false")+"}";
  server.send(200,"application/json",j);
}
void setup(){
  pinMode(PIN_BTN, INPUT_PULLUP);
  pinMode(PIN_LED_OK, OUTPUT); pinMode(PIN_LED_DRY, OUTPUT);
  pinMode(PIN_BUZZ, OUTPUT);
  Wire.begin(SDA_PIN,SCL_PIN);
  if(display.begin(SSD1306_SWITCHCAPVCC,0x3C)){
    display.clearDisplay(); display.setTextSize(1); display.setTextColor(SSD1306_WHITE);
    display.setCursor(0,0); display.println("Soil sensor"); display.display();
  }
  analogReadResolution(12);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  unsigned long t0=millis();
  while(WiFi.status()!=WL_CONNECTED && millis()-t0<8000) delay(200);
  server.on("/", handleRoot);
  server.on("/api", handleApi);
  server.begin();
}
void loop(){
  server.handleClient();
  rawVal=readSoil();
  moisturePct=toPercent(rawVal);
  alarm = moisturePct < threshold;
  digitalWrite(PIN_LED_OK, alarm?LOW:HIGH);
  digitalWrite(PIN_LED_DRY, alarm?HIGH:LOW);
  if(alarm && millis()-lastBuzz>30000){
    // писк 500мс
    tone(PIN_BUZZ, 4000, 500);
    lastBuzz=millis();
  }
  // OLED
  if(display.ssd1306_command){ // dummy check if init ok - use flag
  }
  display.clearDisplay();
  display.setCursor(0,0); display.setTextSize(2); display.print(moisturePct); display.print("%");
  display.setTextSize(1); display.setCursor(0,22); display.print("raw "); display.print(rawVal);
  display.setCursor(0,34); display.print(alarm?"ПОЛЕЙ МЕНЯ!":"Норма");
  if(WiFi.status()==WL_CONNECTED){ display.setCursor(0,46); display.print(WiFi.localIP()); } else { display.setCursor(0,46); display.print("WiFi off"); }
  display.setCursor(0,56); display.print("Удерж. кнопку-калибр.");
  display.display();
  // калибровка: зажать 2с = принять текущее как сухое/влажное? Простое: долгое нажатие - инвертирует порог
  static unsigned long pressStart=0;
  if(digitalRead(PIN_BTN)==LOW){
    if(pressStart==0) pressStart=millis();
    if(millis()-pressStart>2000){
      // калибровка: считаем текущее как "сухо" или "мокро" по второму нажатию
      dryValue = rawVal + 200; // грубо: текущее сухое
      tone(PIN_BUZZ,3000,200); delay(200); tone(PIN_BUZZ,4000,200);
      pressStart=0; delay(1000);
    }
  } else pressStart=0;
  delay(200);
}
